import React, { useState } from 'react';
import { Document, Page, pdfjs } from 'react-pdf';

pdfjs.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjs.version}/pdf.worker.min.js`;

const PDFViewer = ({ file }) => {
  const [numPages, setNumPages] = useState(null);
  const [pageNumber, setPageNumber] = useState(1);
  const [scale, setScale] = useState(1.2);
  const [rotation, setRotation] = useState(0);

  const onDocumentLoadSuccess = ({ numPages }) => {
    setNumPages(numPages);
  };

  return (
    <div style={{ textAlign: 'center' }}>
      <div style={{ marginBottom: '10px' }}>
        <button onClick={() => setPageNumber(Math.max(pageNumber - 1, 1))}>Página Anterior</button>
        <span style={{ margin: '0 10px' }}>Página {pageNumber} de {numPages}</span>
        <button onClick={() => setPageNumber(Math.min(pageNumber + 1, numPages))}>Próxima Página</button>
        <button onClick={() => setScale(scale + 0.2)} style={{ marginLeft: 20 }}>🔍 Zoom +</button>
        <button onClick={() => setScale(Math.max(scale - 0.2, 0.6))}>🔎 Zoom -</button>
        <button onClick={() => setRotation((rotation + 90) % 360)} style={{ marginLeft: 20 }}>⟳ Rotacionar</button>
      </div>

      <Document
        file={file}
        onLoadSuccess={onDocumentLoadSuccess}
        loading="Carregando documento PDF..."
      >
        <Page pageNumber={pageNumber} scale={scale} rotate={rotation} />
      </Document>
    </div>
  );
};

export default PDFViewer;
